def norm(s):return re.sub(r'\\''["'^a-z0-9]'"'\\'','\\'''\\'',html.unescape(s).lower())
for s,f in [('\\''S1'\\'','\\''PMC13581591.xml'\\''),('\\''S2'\\'','\\''PMC13581617.xml'\\''),('\\''S3'\\'','\\''PMC13664187.xml'\\'')]:
    api=back[s]['\\''refs'\\'']; ids={str(x['\\''id'\\'']) for x in api}; titles=[norm(x['\\''title'\\'']) for x in api]
    omissions=[]; pmatch=0;tmatch=0
    for ref in ET.parse('\\''data/papers/'\\''+f).findall('\\''.//ref-list/ref'\\''):
        txt='\\'' '\\''.join(ref.itertext()); pmids={p.text for p in ref.findall('\\''.//pub-id[@pub-id-type=\"pmid\"]'\\'')}
        pmids|={p.get('\\''{http://www.w3.org/1999/xlink}href'\\'') for p in ref.findall('\\''.//ext-link[@ext-link-type=\"pmid\"]'\\'')}
        if pmids & ids: pmatch+=1
        elif any(t and t in norm(txt) for t in titles):tmatch+=1
        else: omissions.append(int(re.sub(r'\\''\\D'\\'','\\'''\\'',ref.findtext('\\''label'\\''))))
